"use client"

import { useEffect, useMemo, useState } from "react"

import { diffsInWorker, diffTextAsync, type AsyncDiffOptions } from "@/lib/diff-async"
import { diffText } from "@/lib/diff-lines"
import type { TextDiff } from "@/lib/diff-types"

type TextDiffInput = Omit<AsyncDiffOptions, "signal">

type Result = { oldText: string; newText: string; key: string; diff: TextDiff }

/**
 * Diffs two texts: during render below the worker threshold, so a small diff never flashes a loading state, and
 * in a Web Worker above it, keeping the last result on screen (`pending`) until the new one arrives. Options are
 * read field by field, so callers can pass them inline.
 */
function useTextDiff(oldText: string, newText: string, options: TextDiffInput = {}) {
  const { algorithm, context, ignoreWhitespace, maxLines, maxChars, maxCost, worker, workerThreshold } = options
  const key = [algorithm, context, ignoreWhitespace, maxLines, maxChars, maxCost].join("|")
  const inWorker = diffsInWorker(oldText, newText, { worker, workerThreshold })
  const now = useMemo(
    () =>
      inWorker
        ? null
        : diffText(oldText, newText, { algorithm, context, ignoreWhitespace, maxLines, maxChars, maxCost }),
    [inWorker, oldText, newText, algorithm, context, ignoreWhitespace, maxLines, maxChars, maxCost],
  )
  const [result, setResult] = useState<Result | null>(null)

  useEffect(() => {
    if (!inWorker) return
    const controller = new AbortController()
    const signal = controller.signal
    diffTextAsync(oldText, newText, {
      algorithm,
      context,
      ignoreWhitespace,
      maxLines,
      maxChars,
      maxCost,
      worker,
      workerThreshold,
      signal,
    }).then(
      (diff) => setResult({ oldText, newText, key, diff }),
      () => {},
    )
    return () => controller.abort()
  }, [
    inWorker,
    oldText,
    newText,
    key,
    algorithm,
    context,
    ignoreWhitespace,
    maxLines,
    maxChars,
    maxCost,
    worker,
    workerThreshold,
  ])

  if (now) return { diff: now, pending: false }
  const current = result && result.oldText === oldText && result.newText === newText && result.key === key
  return { diff: result?.diff ?? null, pending: !current }
}

export { useTextDiff }
export type { TextDiffInput }

"use client"

import { useMemo, type ReactNode } from "react"

import { diffLabels } from "@/components/ui/diff-labels"
import { DiffView, type DiffViewProps } from "@/components/ui/diff-view"
import { toViewFiles } from "@/components/ui/diff-view-model"
import { useTextDiff, type TextDiffInput } from "@/components/ui/use-text-diff"
import { toFileDiff } from "@/lib/diff-lines"
import { cn } from "@/lib/utils"

type TextDiffProps = Omit<DiffViewProps, "files" | "headers"> &
  TextDiffInput & {
    oldText: string
    newText: string
    /** A file name or extension (`"app.tsx"`, `"css"`) that picks the syntax colours. */
    language?: string
    /** Shown while a large diff is computed in a worker, before the first result. */
    loading?: ReactNode
  }

/**
 * Compares two strings line by line: unified or split, line numbers, unchanged regions folded behind "Expand N
 * lines", changed words highlighted, syntax colours, word wrap and find in page across folded and off-screen
 * lines. Large inputs diff in a Web Worker.
 */
function TextDiff({
  oldText,
  newText,
  language = "",
  algorithm,
  context,
  ignoreWhitespace,
  maxLines,
  maxChars,
  maxCost,
  worker,
  workerThreshold,
  loading,
  labels = diffLabels,
  className,
  ...props
}: TextDiffProps) {
  const { diff, pending } = useTextDiff(oldText, newText, {
    algorithm,
    context,
    ignoreWhitespace,
    maxLines,
    maxChars,
    maxCost,
    worker,
    workerThreshold,
  })
  const files = useMemo(() => {
    if (!diff) return []
    const name = language.includes(".") ? language : language ? `file.${language}` : ""
    const [view] = toViewFiles([toFileDiff(diff, oldText, newText, { oldPath: name })])
    return diff.hunks.length > 0 || diff.status !== "ok" ? [{ ...view!, path: "" }] : []
  }, [diff, language, oldText, newText])
  if (!diff) {
    return (
      <div
        data-slot="text-diff-loading"
        aria-busy="true"
        className={cn("p-inset-surface text-muted-foreground", className)}
      >
        {loading ?? labels.loading}
      </div>
    )
  }
  return (
    <DiffView
      {...props}
      files={files}
      labels={labels}
      aria-busy={pending || undefined}
      className={cn("aria-busy:opacity-80", className)}
    />
  )
}

export { TextDiff }
export type { TextDiffProps }
